', new_: ''], [file: 'org/jetbrains/kotlin/idea/base/analysis/api/utils/shortenUtils.kt', old: 'import org.jetbrains.kotlin.analysis.api.permissions.allowAnalysisOnEdt
', new_: ''], [file: 'org/jetbrains/kotlin/idea/base/analysis/api/utils/shortenUtils.kt', old: '@OptIn(KaAllowAnalysisOnEdt::class)
', new_: ''], [file: 'org/jetbrains/kotlin/idea/base/analysis/api/utils/shortenUtils.kt', old: ' val shortenCommand = allowAnalysisOnEdt {
