// CallParameterInfoProvider.kt: isNotSubTypeOf is an internal extension not in public API; // replace with the public isSubtypeOf negated. [file: 'org/jetbrains/kotlin/idea/base/analysis/api/utils/CallParameterInfoProvider.kt', old: 'argumentType.isNotSubTypeOf(parameterForArgument.returnType, subtypingErrorTypePolicy)', new_: '!argumentType.isSubtypeOf(parameterForArgument.returnType, subtypingErrorTypePolicy)'],
