', new_: ''], [file: 'org/jetbrains/kotlin/idea/refactoring/intentions/OperatorToFunctionConverter.kt', old: 'qualifiedExpression.selectorExpression.safeAs<KtCallExpression>()', new_: '(qualifiedExpression.selectorExpression as? KtCallExpression)'], [file: 'org/jetbrains/kotlin/idea/refactoring/intentions/OperatorToFunctionConverter.kt', old: 'receiverExpression.safeAs<KtDotQualifiedExpression>()', new_: '(receiverExpression as? KtDotQualifiedExpression)'], [file: 'org/jetbrains/kotlin/idea/refactoring/intentions/OperatorToFunctionConverter.kt', old: 'element.parent?.safeAs<KtQualifiedExpression>()', new_: '(element.parent as? KtQualifiedExpression)'], [file: 'org/jetbrains/kotlin/idea/refactoring/intentions/OperatorToFunctionConverter.kt', old: 'import org.jetbrains.kotlin.analysis.api.permissions.KaAllowAnalysisFromWriteAction
