// RedundantExplicitTypeArgumentsUtil.kt: isSubTypeOf → isSubtypeOf (Analysis API 2.3.21 rename). [file: 'org/jetbrains/kotlin/idea/k2/refactoring/util/RedundantExplicitTypeArgumentsUtil.kt', old: 'argumentType.isSubTypeOf(sig.returnType)', new_: 'argumentType.isSubtypeOf(sig.returnType)'], // RedundantExplicitTypeArgumentsUtil.kt: isEqualTo → semanticallyEquals (first occurrence in isApplicableType). [file: 'org/jetbrains/kotlin/idea/k2/refactoring/util/RedundantExplicitTypeArgumentsUtil.kt', old: 'return type.isEqualTo(expectedType) ||', new_: 'return type.semanticallyEquals(expectedType) ||'], // RedundantExplicitTypeArgumentsUtil.kt: receiverParameter?.type → receiverParameter?.returnType // (KaReceiverParameterSymbol has no .type property; returnType is inherited from KaCallableSymbol). [file: 'org/jetbrains/kotlin/idea/k2/refactoring/util/RedundantExplicitTypeArgumentsUtil.kt', old: 'resolvedCall.partiallyAppliedSymbol.symbol.receiverParameter?.type', new_: 'resolvedCall.partiallyAppliedSymbol.symbol.receiverParameter?.returnType'], // RedundantExplicitTypeArgumentsUtil.kt: isEqualTo → semanticallyEquals (second occurrence, // inside withNullability call — different pattern from the first occurrence above). [file: 'org/jetbrains/kotlin/idea/k2/refactoring/util/RedundantExplicitTypeArgumentsUtil.kt', old: 'type.withNullability(KaTypeNullability.NULLABLE).isEqualTo(expectedType)', new_: 'type.withNullability(KaTypeNullability.NULLABLE).semanticallyEquals(expectedType)'],
// KotlinPsiUtils.kt: remove createArgumentWithoutName — identical function exists in ArgumentUtils.kt // (same package, same parameter types → conflicting overload). [file: 'org/jetbrains/kotlin/idea/codeinsight/utils/KotlinPsiUtils.kt', old: 'fun createArgumentWithoutName(argument: KtValueArgument, isVararg: Boolean = false, isArrayOf: Boolean = false): List<KtValueArgument> {
 if (!argument.isNamed()) return listOf(argument.copied())
 val argumentExpr = argument.getArgumentExpression() ?: return emptyList()
 val psiFactory = KtPsiFactory(argument)
 return when {
 isVararg && argumentExpr is KtCollectionLiteralExpression ->
 argumentExpr.getInnerExpressions().map { psiFactory.createArgument(it) }

 isVararg && argumentExpr is KtCallExpression && isArrayOf ->
 argumentExpr.valueArguments.map { psiFactory.createArgument(it.getArgumentExpression()) }

 else -> listOf(psiFactory.createArgument(argumentExpr, name = null, isVararg))
 }
}
', new_: ''], // KotlinPsiUtils.kt: remove isReferenceToBuiltInEnumFunction — requires ENUM_STATIC_METHOD_NAMES // and canBeReferenceToBuiltInEnumFunction from EnumUtils.kt which we don't copy. [file: 'org/jetbrains/kotlin/idea/codeinsight/utils/KotlinPsiUtils.kt', old: 'context(KaSession)
fun KtCallExpression.isReferenceToBuiltInEnumFunction(): Boolean {
 val calleeExpression = this.calleeExpression ?: return false
 return (calleeExpression as? KtSimpleNameExpression)?.getReferencedNameAsName() in ENUM_STATIC_METHOD_NAMES && calleeExpression.isSynthesizedFunction()
}

context(KaSession)
fun KtCallableReferenceExpression.isReferenceToBuiltInEnumFunction(): Boolean {
 return this.canBeReferenceToBuiltInEnumFunction() && this.callableReference.isSynthesizedFunction()
}
', new_: ''],
// OperatorToFunctionConverter.kt: LanguageFeature.OperatorRem was removed in Kotlin 2.3.21 // (it was a compatibility flag for pre-1.1 operator rem; rem is always supported in Kotlin 2.x). [file: 'org/jetbrains/kotlin/idea/refactoring/intentions/OperatorToFunctionConverter.kt', old: 'val remSupported = element.languageVersionSettings.supportsFeature(LanguageFeature.OperatorRem)', new_: 'val remSupported = true'],
// InsertExplicitTypeArgumentsUtils.kt: KaType sealed hierarchy may have new subtypes in 2.3.21; // add else branch to make the when expression exhaustive. [file: 'org/jetbrains/kotlin/idea/codeinsight/utils/InsertExplicitTypeArgumentsUtils.kt', old: ' is KaTypeParameterType, is KaCapturedType, is KaDynamicType -> false
}', new_: ' is KaTypeParameterType, is KaCapturedType, is KaDynamicType -> false
 else -> false
}'],
// InsertExplicitTypeArgumentsUtils.kt: use WITH_SHORT_NAMES renderer so that inferred type // arguments are rendered without package qualifiers (e.g. "Int" not "kotlin.Int"). // The original code relied on ShortenReferencesFacility which is unavailable in standalone mode. [file: 'org/jetbrains/kotlin/idea/codeinsight/utils/InsertExplicitTypeArgumentsUtils.kt', old: 'import org.jetbrains.kotlin.types.Variance
', new_: 'import org.jetbrains.kotlin.analysis.api.renderer.types.impl.KaTypeRendererForSource
import org.jetbrains.kotlin.types.Variance
'], [file: 'org/jetbrains/kotlin/idea/codeinsight/utils/InsertExplicitTypeArgumentsUtils.kt', old: 'add(type.render(position = Variance.IN_VARIANCE))', new_: 'add(type.render(KaTypeRendererForSource.WITH_SHORT_NAMES, position = Variance.IN_VARIANCE))'],
// ExplicitLambdaSignatureUtil.kt: use WITH_SHORT_NAMES renderer for the same reason. [file: 'org/jetbrains/kotlin/idea/refactoring/util/ExplicitLambdaSignatureUtil.kt', old: 'import org.jetbrains.kotlin.types.Variance
', new_: 'import org.jetbrains.kotlin.analysis.api.renderer.types.impl.KaTypeRendererForSource
import org.jetbrains.kotlin.types.Variance
'], [file: 'org/jetbrains/kotlin/idea/refactoring/util/ExplicitLambdaSignatureUtil.kt', old: 'param.returnType.render(position = Variance.IN_VARIANCE)', new_: 'param.returnType.render(KaTypeRendererForSource.WITH_SHORT_NAMES, position = Variance.IN_VARIANCE)'], // ExplicitLambdaSignatureUtil.kt: fix else-branch (implicit 'it' param has null psi) to also use WITH_SHORT_NAMES. // param.render() uses the default renderer which produces fully qualified names; instead render // name + type explicitly. [file: 'org/jetbrains/kotlin/idea/refactoring/util/ExplicitLambdaSignatureUtil.kt', old: '} else param.render()', new_: '} else param.name.asString() + ": " + param.returnType.render(KaTypeRendererForSource.WITH_SHORT_NAMES, position = Variance.IN_VARIANCE)'], ]
patches.each { p -> def f = new File(srcDir, p.file) if (!f.exists()) { log.warn("patch target not found: ${p.file}"); return } def text = f.text if (!text.contains(p.old)) { log.warn("patch target not found in ${p.file}: '${p.old.take(80)}'"); return } f.text = text.replace(p.old, p.new_) log.info("Patched ${p.file}") }
